// === Tab: mySketch ===
let lapse = 0;    // タイマー
let num = 1000;   // 粒子の数
let pos = [];     // 位置配列
let vel = [];     // 速度配列
let maxFrames = 1000; // リセットするフレーム数の閾値

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
  colorMode(HSB, 255);
  for (let i = 0; i < num; i++) {
    pos[i] = createVector(width / 2, height / 2);
    vel[i] = createVector(0, 0);
  }
}

function draw() {
  for (let i = 0; i < pos.length; i++) {
    pos[i].add(vel[i]);
    let rotation = random(TWO_PI);
    vel[i].x += cos(rotation) * 0.1;
    vel[i].y += sin(rotation) * 0.1;

    if (pos[i].x < 0 || pos[i].x > width || pos[i].y < 0 || pos[i].y > height) {
      vel[i].mult(0);
    }

    strokeWeight(1);
    stroke((frameCount * 2 % 255), 255, 255, 4);
    line(pos[i].x, pos[i].y, pos[i].x + vel[i].x * 10, pos[i].y + vel[i].y * 10);
  }

  // 一定フレーム数経過後にリセット
  if (frameCount % maxFrames === 0) {
    setup();
  }
}

